  function status(title,sub,time){return `<div class="status-row"><i class="status-dot"></i><div><b>${title}</b><small>${sub}</small></div><time>${time}</time></div>`}
  function wholeDashboardButtonMarkup(button,index){const [kind,target]=String(button.target||'page:quotes').split(':');const trigger=kind==='action'?`data-action="${esc(target)}"`:`data-page="${esc(target)}"`;return `<div class="whole-action-shell"><button class="btn ${button.primary?'primary':''}" ${trigger}>${esc(button.label)}</button>${wholeDashboardEditing?`<span class="whole-action-tools"><button class="btn small" data-action="whole-dashboard-edit-button" data-index="${index}">编辑</button><button class="btn small danger" data-action="whole-dashboard-delete-button" data-index="${index}" aria-label="删除${esc(button.label)}">删除</button></span>`:''}</div>`}
  function wholeDashboardMetricMarkup(item,index){const routes={'我负责的客户':'whole/customers','进行中的工地':'whole/projects','待确认变更':'whole/customers','本月项目支出':'all/finance','待完成跟进':'whole/customers'};return `<div class="whole-metric-shell">${metricLink(esc(item.label),esc(item.value),esc(item.note),esc(item.glyph||'◈'),routes[item.label]||'whole/customers')}${wholeDashboardEditing?`<button class="btn small whole-metric-edit" data-action="whole-dashboard-edit-metric" data-index="${index}">编辑卡片</button>`:''}</div>`}
  function wholePanelEditAction(id,normal=''){return `${normal}${wholeDashboardEditing?`<button class="btn small" data-action="whole-dashboard-edit-panel" data-panel="${id}">编辑标题</button>`:''}`}
  function wholeHome(){const cfg=wholeDashboard,customerPanel=role==='foreman'?panel('我的工地','仅显示分配给当前工长的工地和节点','<p class="empty">请从工地进程进入分配给我的项目。</p>'):panel(esc(cfg.panels.customers.title),esc(cfg.panels.customers.subtitle),customerRows(scopedCustomers()),wholePanelEditAction('customers',`<button class="btn small" data-page="customers">${esc(cfg.panels.customers.button)}</button>`)),actions=`${cfg.buttons.map(wholeDashboardButtonMarkup).join('')}${role==='owner'?(wholeDashboardEditing?`<button class="btn" data-action="whole-dashboard-copy">编辑页面文字</button><button class="btn" data-action="whole-dashboard-add-button">＋ 添加快捷按钮</button><button class="btn" data-action="whole-dashboard-reset">恢复默认</button><button class="btn primary" data-action="whole-dashboard-done">完成编辑</button>`:`<button class="btn primary" data-action="whole-dashboard-edit">编辑本页</button>`):''}`;const metrics=role==='owner'?cfg.metrics.slice(0,4):[...cfg.metrics.slice(0,3),cfg.metrics[4]];return `${head(esc(cfg.kicker),esc(cfg.title),esc(cfg.subtitle),actions)}${wholeDashboardEditing?'<div class="dashboard-edit-note">正在编辑这张页面：可修改页面说明、快捷按钮、数据卡片和区块标题；更改只保存在当前浏览器。</div>':''}<div class="cards">${metrics.map((x,i)=>wholeDashboardMetricMarkup(x,role==='owner'?i:4)).join('')}</div><div class="grid-2">${panel(esc(cfg.panels.progress.title),esc(cfg.panels.progress.subtitle),`<div class="pipeline">${[['待量房','3'],['报价中','4'],['待签约','2'],['施工中','5'],['主材进场','3'],['竣工验收','1']].map((x,i)=>`<div class="pipeline-step ${i===3?'active':''}"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</div>`,wholePanelEditAction('progress'))}${panel(esc(cfg.panels.latest.title),esc(cfg.panels.latest.subtitle),`<div class="status-list">${status('华强城 · 客厅吊顶尺寸变更','设计师A记录，待工长现场复核','09:40')}${status('建业桂园 · 瓷砖型号确认','客户已确认，材料单待上传','昨天')}${status('万和城 · 水电定位完成','工长更新进度，待设计师回访','昨天')}</div>`,wholePanelEditAction('latest'))}</div>${customerPanel}`}
  function customHome(){return `${head('CUSTOM CABINETRY · 全屋定制','定制业务总览','从客户来源和量尺沟通，到报价、材料确认、下单与工厂生产。',`<button class="btn" data-page="customers">查看客户与报价</button><button class="btn primary" data-action="new-customer-for-quote">＋ 新建客户</button>`)}<div class="cards">${metricLink('待报价客户','5','已完成量尺 <strong>3 户</strong>','♙','custom/customers')}${metricLink('已确认报价','8','本月报价总额 · 示例','▤','custom/quotes/list')}${metricLink('待材料确认','3','板材/门板信息未齐','▧','custom/customers')}${role==='owner'?metricLink('工厂待接单','4','需核对尺寸及五金清单','▣','factory/production'):metricLink('我的待办','4','材料确认和客户回访','◷','custom/customers')}</div><div class="grid-2">${panel('定制订单链路','报价确认后进入下单核对和生产',`<div class="pipeline">${[['沟通量尺','4'],['报价中','5'],['确认方案','3'],['拆单复核','2'],['工厂生产','4'],['安装售后','2']].map((x,i)=>`<div class="pipeline-step ${i===3?'active':''}"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</div>`)}${panel('下单前检查','材料、尺寸、工艺和五金分别确认',`<div class="status-list">${status('材料信息','板芯、门板、颜色、厚度待复核','3 项')}${status('尺寸与现场图','量尺尺寸需与CAD/照片对应','2 户')}${status('五金及特殊工艺','玻璃门、灯带、拉篮等清单核对','1 户')}</div>`)}</div>${panel('近期定制客户','报价和工厂交接都回到客户项目下',customerRows(sampleCustomers.filter(c=>c.type!=='整装')),)}`}
  function factoryHome(){return `${head('FACTORY FLOOR · 工厂生产','工厂生产总览',role==='owner'?'订单、加工量、库存和费用按户归集；原始票据可留档复核。':'查看生产任务、材料领用和加工数据，现场异常及时记录。',`<button class="btn" data-page="inventory">五金库存</button><button class="btn primary" data-page="production">＋ 记录生产数据</button>`)}<div class="cards">${metric('生产中订单','8','本周计划交付 <strong>3 户</strong>','▧')}${metric('待领料任务','4','板材、五金待出库','⇣')}${metric('库存预警','2','低于设置的安全库存','⚠')}${role==='owner'?metric('本月工厂支出',money(49350),'含采购、邮费、耗材等','￥'):metric('待填生产数据','3','开料/封边/打孔记录','◷')}</div><div class="grid-2">${panel('今日生产任务','生产单关联订单、图纸和材料要求',`<div class="status-list">${status('Q-1028 · 华强城衣柜','开料 18.6㎡ · 封边 42米 · 待打孔','进行中')}${status('Q-1024 · 建业桂园橱柜','门板到货待检，五金未齐','待料')}${status('Q-1021 · 万和城鞋柜','完成包装，待安排配送','待发货')}</div>`)}${panel('今日加工汇总','以实际录入数据统计（示例）',`<div class="stock-grid"><div class="stock-card"><span>开料面积</span><b>68.4㎡</b><small>本日累计</small></div><div class="stock-card"><span>封边长度</span><b>186米</b><small>本日累计</small></div><div class="stock-card"><span>打孔面积</span><b>42.7㎡</b><small>本日累计</small></div></div>`)}</div>${panel('单据与费用待办','采购单、报货单和费用凭证关联到每户',`<div class="status-list">${status('板材报货回传单','3 张待确认订单归属','11:20')}${status('五金采购票据','2 笔待登记入库','10:05')}${status('快递与耗材报销','1 笔待管理者核对','昨天')}</div>`)}`}
  function customers(){const owner=role==='owner',visibleCustomers=scopedCustomers(),drilled=customerDrill==='unassigned'?visibleCustomers.filter(c=>!c.owner||c.owner==='未分配'):customerDrill==='followup'?visibleCustomers.filter(c=>c.due&&c.due!=='未安排'):customerDrill==='new'?visibleCustomers.filter(c=>String(c.id||'').startsWith('C-')):visibleCustomers;return `${head('CUSTOMER RELATIONSHIP · 客户管理','客户与跟进',owner?'统筹客户来源、员工分配与跟进质量。转派时保留客户历史记录。':'记录客户来源、需求和每次沟通；下一步跟进有提醒。',`<button class="btn primary" data-action="new-customer">＋ 新建客户</button>`)}<div class="cards">${metricLink('客户总数',visibleCustomers.length,'当前客户档案','♙','all/customers/all')}${metricLink('待跟进',visibleCustomers.filter(c=>c.due&&c.due!=='未安排').length,'已有联系计划','◷','all/customers/followup')}${metricLink('未分配',visibleCustomers.filter(c=>!c.owner||c.owner==='未分配').length,'待负责人处理','!','all/customers/unassigned')}${metricLink('本机新增记录',visibleCustomers.filter(c=>String(c.id||'').startsWith('C-')).length,'此浏览器创建的客户','▤','all/customers/new')}</div><div class="toolbar"><label class="search">⌕<input id="customerSearch" placeholder="搜索客户、小区或来源"></label><select class="select" id="stageFilter"><option value="">全部阶段</option><option>线索</option><option>量房沟通</option><option>报价中</option><option>已签约</option><option>施工中</option></select><select class="select"><option>全部业务</option><option>整装</option><option>全屋定制</option></select><span class="spacer"></span><span class="section-kicker">${drilled.length} 位客户 · 演示数据</span></div>${panel(owner?'客户与分配':'我的客户','来源、负责人、当前阶段、下次跟进集中查看',`<div id="customerRows">${customerRows(drilled)}</div>`)}`}
