  function quoteCalculatedQuantity(r){const mode=$('[data-unit]',r)?.value,q=Number($('[data-qty]',r)?.value||0),w=Number($('[data-width]',r)?.value||0),h=Number($('[data-height]',r)?.value||0),d=Number($('[data-depth]',r)?.value||0),deduct=Number($('[data-deduct]',r)?.value||0);if(mode==='投影面积')return Math.max(0,w*h/1000000-deduct)*q;if(mode==='展开面积')return Math.max(0,2*(w+h)*d/1000000-deduct)*q;if(mode==='延米')return w*q/1000;return q}
  function recalc(){const rows=$$('#quoteLines tr');if(quotePricingMode==='split')rows.forEach(r=>{const p=$('[data-price]',r),sum=Number($('[data-labor-price]',r)?.value||0)+Number($('[data-material-price]',r)?.value||0);if(p)p.value=sum.toFixed(2);const label=$('[data-combined-price]',r);if(label)label.textContent=money(sum)});let total=0,costTotal=0,marginTotal=0;rows.forEach(r=>{const quantity=quoteCalculatedQuantity(r),p=Number($('[data-price]',r)?.value||0),c=Number($('[data-cost]',r)?.value||0),amount=quantity*p,cost=quantity*c,margin=amount-cost;total+=amount;costTotal+=cost;marginTotal+=margin;if($('[data-amount]',r))$('[data-amount]',r).textContent=money(amount);if($('[data-measure-qty]',r))$('[data-measure-qty]',r).textContent=`${quantity.toFixed(2)} ${$('.quote-unit-hint',r)?.textContent||''}`;if($('[data-margin]',r))$('[data-margin]',r).textContent=money(margin);const unitHint=$('.quote-unit-hint',r);if(unitHint){const mode=$('[data-unit]',r)?.value;unitHint.textContent=mode==='投影面积'||mode==='展开面积'?'㎡':mode==='延米'?'m':unitHint.dataset.unitLabel||'项'}});if($('#quoteTotal'))$('#quoteTotal').textContent=money(total);if($('#quoteCostTotal'))$('#quoteCostTotal').textContent=money(costTotal);if($('#quoteMarginTotal'))$('#quoteMarginTotal').textContent=money(marginTotal);const count=rows.length;if($('#quoteLineCount'))$('#quoteLineCount').textContent=`${count} 个项目`;if($('#quoteSummaryCount'))$('#quoteSummaryCount').textContent=`${count} 项`;if($('#quoteEmpty'))$('#quoteEmpty').hidden=count>0;if($('#quoteMissing'))$('#quoteMissing').textContent=count?'逐项核对尺寸 / 数量':'待添加项目'}
