  function migrateFactoryJobs(){const legacy={'待排产':'已订货','生产中':'开料中','待安装':'已完成待出货','已交付':'出货完成','待复核':'货已到厂','待领料':'已订货','待发货':'已完成待出货'};factoryJobRecords=factoryJobRecords.map(j=>{j.status=legacy[j.status]||j.status||'已订货';if(!factoryProcessStages.includes(j.status))j.status='已订货';j.statusHistory=Array.isArray(j.statusHistory)?j.statusHistory:[{status:j.status,time:'历史订单',note:'旧记录状态迁移'}];if(!j.community){const parts=String(j.customer||'').split('·').map(x=>x.trim());if(parts.length>1){j.customer=parts.shift();j.community=parts.join(' · ')}}j.product=j.product||'定制订单';j.costLines=Array.isArray(j.costLines)?j.costLines:[];return j})}
